function validate([n, k]) {
  if (!Number.isInteger(n) || n < 1 || n > 50) return 'n is a whole number from 1 to 50.';
  if (!Number.isInteger(k) || k < 1 || k > 100000) return 'k is a whole number from 1 to 10^5.';
  let before = k, current = k * k;
  const tooBig = 'The answer must be at most 2^31 - 1; use fewer posts or colors.';
  if (n >= 2 && current > 2147483647) return tooBig;
  for (let i = 3; i <= n; i++) {
    [before, current] = [current, (k - 1) * (before + current)];
    if (current > 2147483647) return tooBig;
  }
  return null;
}

