function numWays(n, k) {
  if (n === 1) {
    return k;
  }
  const dp = new Array(n + 1).fill(0);
  dp[1] = k;
  dp[2] = k * k;

  for (let i = 3; i <= n; i++) {
    dp[i] = (k - 1) * (dp[i - 1] + dp[i - 2]);
  }
  return dp[n];
}

brute:
function numWays(n, k) {
  // A painting is a row of blocks of one or two equal posts, and neighbouring blocks differ in color.
  // With b blocks there are C(b, n - b) ways to choose which blocks are doubles and k * (k - 1)^(b - 1) colorings.
  let total = 0;
  for (let blocks = Math.ceil(n / 2); blocks <= n; blocks++) {
    const doubles = n - blocks;
    let choose = 1;
    for (let j = 1; j <= doubles; j++) choose = choose * (blocks - doubles + j) / j;
    total += choose * k * (k - 1) ** (blocks - 1);
  }
  return total;
}

