function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const fits = (n, k) => {
    let before = k, current = k * k;
    if (n >= 2 && current > 2147483647) return false;
    for (let i = 3; i <= n; i++) {
      [before, current] = [current, (k - 1) * (before + current)];
      if (current > 2147483647) return false;
    }
    return true;
  };
  if (size !== 'large') {
    const n = int(1, 8);
    return [n, int(1, 5)];
  }
  // More colors never mean fewer ways, so search for the most colors whose answer still fits.
  const n = int(1, 50);
  let low = 1, high = 100000;
  while (low < high) {
    const mid = Math.ceil((low + high) / 2);
    if (fits(n, mid)) low = mid;
    else high = mid - 1;
  }
  return [n, rand() < 0.5 ? low : int(1, low)];
}
